import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    const generation = session.generation;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}
import { boardCode, SEED_MAX } from '../deck.ts';

const UINT32_RANGE = 2 ** 32;
const RANDOM_LIMIT = Math.floor(UINT32_RANGE / SEED_MAX) * SEED_MAX;

export function freshBoardCode(size: number, previousSeed?: number): string {
  const buffer = new Uint32Array(1);
  for (;;) {
    crypto.getRandomValues(buffer);
    const draw = buffer[0];
    if (draw === undefined || draw >= RANDOM_LIMIT) continue;
    const seed = (draw % SEED_MAX) + 1;
    if (seed !== previousSeed) return boardCode(size, seed);
  }
}
export const GRID_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
const BOARD_VERSION = 'np1';
export const SEED_MAX = 2_147_483_646;
const PRNG_MODULUS = SEED_MAX + 1;
const PRNG_MULTIPLIER = 16_807;

export interface Board {
  readonly boardCode: string;
  readonly size: number;
  readonly seed: number;
  readonly deck: readonly number[];
}

export function isValidSize(value: number): boolean {
  return GRID_SIZES.some((size) => size === value);
}

export function nextRandomState(state: number): number {
  return (state * PRNG_MULTIPLIER) % PRNG_MODULUS;
}

export function parseBoardCode(code: string): { size: number; seed: number } | null {
  const parts = new RegExp(`^${BOARD_VERSION}-([1-9]\\d*)-([1-9]\\d*)$`).exec(code);
  if (!parts) return null;
  const size = Number(parts[1]);
  const seed = Number(parts[2]);
  return isValidSize(size) && Number.isSafeInteger(seed) && seed <= SEED_MAX
    ? { size, seed }
    : null;
}

export function boardCode(size: number, seed: number): string {
  const code = `${BOARD_VERSION}-${size}-${seed}`;
  if (!parseBoardCode(code)) throw new Error('Invalid board code.');
  return code;
}

export function generateBoard(code: string): Board {
  const parsed = parseBoardCode(code);
  if (!parsed) throw new Error('Invalid board code.');
  const deck = Array.from({ length: parsed.size ** 2 }, (_, index) => Math.floor(index / 2));
  let state = parsed.seed;
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const bound = index + 1;
    const limit = Math.floor(SEED_MAX / bound) * bound;
    let draw: number;
    do {
      state = nextRandomState(state);
      draw = state - 1;
    } while (draw >= limit);
    const other = draw % bound;
    const currentFace = deck[index];
    const otherFace = deck[other];
    if (currentFace === undefined || otherFace === undefined)
      throw new Error('Deck index out of range.');
    deck[index] = otherFace;
    deck[other] = currentFace;
  }
  return Object.freeze({ boardCode: code, ...parsed, deck: Object.freeze(deck) });
}
export function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function isNonnegativeSafeInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

export function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return (
    Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key))
  );
}

export function isWithinBytes(text: string, maxBytes: number): boolean {
  return new TextEncoder().encode(text).byteLength <= maxBytes;
}

// No JSON text parses to undefined, so it marks malformed input.
export function parseJson(text: string): unknown {
  try {
    const value: unknown = JSON.parse(text);
    return value;
  } catch {
    return undefined;
  }
}
import { createGame, MOVES_MAX, ELAPSED_MAX_MS } from './game.ts';
import { parseBoardCode } from './deck.ts';
import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  isWithinBytes,
  parseJson,
} from './saved-format.ts';
import { readMatched, readSelection } from './snapshot-selection.ts';
import { SelectionKind } from './selection.ts';
import type { GameState } from './game.ts';

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_MAX_BYTES = 65_536;
export const SNAPSHOT_KEYS = [
  'version',
  'boardCode',
  'matched',
  'selection',
  'moves',
  'elapsedMs',
  'started',
] as const;

export function encodeSnapshot(state: GameState): string {
  return JSON.stringify(
    {
      version: SNAPSHOT_VERSION,
      boardCode: state.boardCode,
      matched: [...state.matched].sort((left, right) => left - right),
      // Active time keeps its fractions in play. Export writes whole milliseconds, and rounding
      // pending time up keeps a mismatch at 1ms or more.
      selection:
        state.selection.kind === SelectionKind.mismatch
          ? { ...state.selection, remainingMs: Math.ceil(state.selection.remainingMs) }
          : state.selection,
      moves: state.moves,
      elapsedMs: Math.floor(state.elapsedMs),
      started: state.started,
    },
    null,
    2,
  );
}

export function decodeSnapshot(text: string): GameState | null {
  const value = isWithinBytes(text, SNAPSHOT_MAX_BYTES) ? parseJson(text) : undefined;
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, SNAPSHOT_KEYS) ||
    value.version !== SNAPSHOT_VERSION
  )
    return null;
  if (typeof value.boardCode !== 'string' || !parseBoardCode(value.boardCode)) return null;
  if (
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves > MOVES_MAX ||
    !isNonnegativeSafeInteger(value.elapsedMs) ||
    value.elapsedMs > ELAPSED_MAX_MS ||
    typeof value.started !== 'boolean'
  )
    return null;
  const initial = createGame(value.boardCode);
  const matched = readMatched(value.matched, initial);
  if (!matched) return null;
  const selection = readSelection(value.selection, initial, matched);
  if (!selection) return null;
  const state: GameState = {
    ...initial,
    matched,
    selection,
    moves: value.moves,
    elapsedMs: value.elapsedMs,
    started: value.started,
  };
  const minimumMoves = matched.length / 2 + (selection.kind === SelectionKind.mismatch ? 1 : 0);
  if (state.moves < minimumMoves) return null;
  if (
    !state.started &&
    (state.moves !== 0 ||
      state.elapsedMs !== 0 ||
      matched.length !== 0 ||
      selection.kind !== SelectionKind.closed)
  )
    return null;
  if (state.started && state.moves === 0 && selection.kind === SelectionKind.closed) return null;
  return state;
}

import assert from 'node:assert/strict';
import { before, after, test as nodeTest } from 'node:test';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { basename, join } from 'node:path';
import { chromium, expect as playwrightExpect } from '@playwright/test';
import { spawnSync } from 'node:child_process';
import { REFERENCE_ROOT, serveArtifact } from './artifact-server.ts';
import type { Browser, BrowserContext, BrowserContextOptions, Page } from '@playwright/test';

const BROWSER_TEMP = join(REFERENCE_ROOT, '.browser-work');
const RESULTS = join(REFERENCE_ROOT, 'test-results');
const CHROMIUM_VERSION = '156.0.8078.4';
const EXECUTABLE_ENV = 'PLAYWRIGHT_CHROMIUM_EXECUTABLE';
// Set to 1 for named-combination evidence. Other supported runtimes run and record their versions.
const NAMED_COMBINATION_ENV = 'NEON_PAIRS_NAMED_COMBINATION';
const NAMED_COMBINATION = {
  node: '26.12.1',
  npm: '11.20.0',
  playwright: '1.64.1',
  chromium: CHROMIUM_VERSION,
};
// Playwright hides scrollbars by default. Visible ones take layout space, as on a Windows desktop.
const HIDE_SCROLLBARS = '--hide-scrollbars';
export const Scrollbars = { hidden: 'hidden', visible: 'visible' } as const;
type ScrollbarMode = (typeof Scrollbars)[keyof typeof Scrollbars];
// A busy verifier runs many browsers at once, so a single wait gets more than Playwright's 5s default.
export const expect = playwrightExpect.configure({ timeout: 15_000 });
// Most journeys fit the standard limit. The accessibility journey and the large boards take the long one.
export const TestTimeouts = { standard: 30_000, long: 90_000 } as const;
// npm names itself and its version to every script it runs, so a browser file needs no npm process of its own.
const NPM_AGENT_ENV = 'npm_config_user_agent';
let browser: Browser | undefined;
let scrollbarBrowser: Promise<Browser> | undefined;
let artifact: Awaited<ReturnType<typeof serveArtifact>> | undefined;

before(async () => {
  await mkdir(BROWSER_TEMP, { recursive: true });
  await mkdir(RESULTS, { recursive: true });
  process.env.TEMP = BROWSER_TEMP;
  process.env.TMP = BROWSER_TEMP;
  const npm = /^npm\/(\S+)/.exec(process.env[NPM_AGENT_ENV] ?? '')?.[1] ?? npmVersion();
  const playwright: unknown = JSON.parse(
    await readFile(new URL(import.meta.resolve('@playwright/test/package.json')), 'utf8'),
  );
  assert.ok(playwright && typeof playwright === 'object' && 'version' in playwright);
  browser = await launch(Scrollbars.hidden);
  const runtime = {
    node: process.versions.node,
    npm,
    playwright: String(playwright.version),
    chromium: browser.version(),
  };
  const named = process.env[NAMED_COMBINATION_ENV] === '1';
  await writeFile(
    join(RESULTS, 'browser-runtime.json'),
    JSON.stringify({ ...runtime, namedCombination: named }, null, 2),
  );
  if (named) assert.deepEqual(runtime, NAMED_COMBINATION, 'T03 named combination');
  artifact = await serveArtifact();
});

after(async () => {
  await browser?.close();
  await (await scrollbarBrowser)?.close();
  await artifact?.close();
});

function launch(scrollbars: ScrollbarMode): Promise<Browser> {
  const executable = process.env[EXECUTABLE_ENV];
  return chromium.launch({
    headless: true,
    ...(executable ? { executablePath: executable } : {}),
    ...(scrollbars === Scrollbars.visible ? { ignoreDefaultArgs: [HIDE_SCROLLBARS] } : {}),
  });
}

interface BrowserFixture {
  browser: Browser;
  context: BrowserContext;
  page: Page;
  gameURL: string;
}
interface Artifacts {
  outputPath(file: string): string;
}

function npmVersion(): string {
  const npmResult =
    process.platform === 'win32'
      ? spawnSync('cmd.exe', ['/d', '/c', 'npm --version'], { encoding: 'utf8' })
      : spawnSync('npm', ['--version'], { encoding: 'utf8' });
  assert.equal(npmResult.status, 0, 'T03 npm version command');
  return npmResult.stdout.trim();
}

export function test(
  name: string,
  body: (fixture: BrowserFixture, artifacts: Artifacts) => Promise<void>,
  options: BrowserContextOptions = {},
  scrollbars: ScrollbarMode = Scrollbars.hidden,
  timeout: number = TestTimeouts.standard,
): void {
  nodeTest(name, { timeout }, async (t) => {
    if (!browser || !artifact) throw new Error('Browser verification did not start.');
    const owner =
      scrollbars === Scrollbars.visible ? await (scrollbarBrowser ??= launch(scrollbars)) : browser;
    const context = await owner.newContext(options);
    t.after(() => context.close());
    const page = await context.newPage();
    const pageErrors: string[] = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));
    const directory = join(RESULTS, name.replace(/[^a-z0-9]+/gi, '-'));
    await mkdir(directory, { recursive: true });
    const artifacts = {
      outputPath(file: string): string {
        if (basename(file) !== file) throw new Error('Expected an artifact filename.');
        return join(directory, file);
      },
    };
    await body({ browser: owner, context, page, gameURL: artifact.url }, artifacts);
    assert.deepEqual(pageErrors, []);
  });
}
